func probeEvidenceBundle(t *testing.T, sp Sprint, qaMap QAMap, shard QAShard, now time.Time) (QAEvidencePublication, QAAssessmentRecord) {
	t.Helper()
	plan, err := FreezeQAEvidencePlan(sp.Project, sp.Slug, QAEvidencePlan{
		AttemptID: qaMap.SemanticAttemptID, ShardID: shard.ID, ExpectationRefs: shard.ExpectationRefs,
		Kind: QACheckFact, ConfirmationCondition: "check passes", RefutationCondition: "check fails", InconclusiveCondition: "check incomplete",
		ApprovedPaths: []string{"internal/a.go"}, Executable: "true", Timeout: time.Minute, OutputLimit: 1024,
		CleanupRequired: true, GovernedInputFingerprint: qaMap.GovernedInputFingerprint,
		ImplementationFingerprint: qaMap.ImplementationFingerprint, MapFingerprint: testQAFingerprint,
	}, qaMap.Budgets, now)
	if err != nil {
		t.Fatal(err)
	}
	record := QAEvidenceRecord{SchemaVersion: QAEvidenceSchemaVersion, ID: mustProbeID(t, "evidence", sp, plan.ID, "probe"), PlanID: plan.ID,
		AttemptID: plan.AttemptID, ShardID: plan.ShardID, WorkspaceID: "opaque", WorkspaceIdentity: strings.Repeat("d", 64),
		TargetIdentityBefore: strings.Repeat("e", 64), TargetIdentityAfter: strings.Repeat("e", 64),
		GovernedInputFingerprint: plan.GovernedInputFingerprint, ImplementationFingerprint: plan.ImplementationFingerprint, MapFingerprint: plan.MapFingerprint,
		Outcome: QAEvidencePass, ReasonCode: "check_passed", Repeatable: true, Contained: true,
		Cleanup:  QACleanupFacts{Attempted: true, DescendantsTerminated: true, WorkspaceRemoved: true, Complete: true},
		CompletedAt: now}
	adjudication, err := AdjudicateQA(QAAdjudicationRequest{Project: sp.Project, Sprint: sp.Slug, AttemptID: qaMap.SemanticAttemptID,
		MapFingerprint: plan.MapFingerprint, Plans: []QAEvidencePlan{plan}, Evidence: []QAEvidenceRecord{record}, Budgets: qaMap.Budgets, Now: now})
	if err != nil {
		t.Fatal(err)
	}
	assessment := QAAssessmentRecord{SchemaVersion: QAEvidenceSchemaVersion, ID: mustProbeID(t, "assessment", sp, qaMap.SemanticAttemptID, "probe"),
		AttemptID: qaMap.SemanticAttemptID, ReviewVerdict: ReviewPass, ReviewFingerprint: testQAFingerprint,
		Assessment: AssessmentPass, EvidenceTotal: 1, NextAction: "done", CompletedAt: now}
	report, err := RenderQAReport(sp.Project, sp.Slug, qaMap.GovernedInputFingerprint, []QAEvidenceRecord{record}, adjudication, assessment)
	if err != nil {
		t.Fatal(err)
	}
	return QAEvidencePublication{Plans: []QAEvidencePlan{plan}, Records: []QAEvidenceRecord{record}, Adjudication: &adjudication, Assessment: &assessment, Report: report, Budgets: qaMap.Budgets}, assessment
}

func mustProbeID(t *testing.T, kind string, sp Sprint, parent string, value any) string {
	t.Helper()
	id, err := NewQAV2ID(kind, sp.Project, sp.Slug, parent, value)
	if err != nil {
		t.Fatal(err)
	}
	return id
}

// Probe 1: re-publishing an evidence bundle for the SAME semantic attempt with
// only wall-clock differences must succeed for an idempotent rerun; the store
// treats timestamp-bearing bytes under deterministic IDs as immutable.
func TestProbeEvidencePublishTwiceConflicts(t *testing.T) {
	root, sp, publication := qaPublicationFixture(t)
	qaMap := *publication.Map
	shard := qaMap.Shards[0]
	token := QAWriterToken{RunID: "run-1", OperationalAttemptID: "op-1", FencingGeneration: 1}
	store := NewQAStore(root, sp).WithWriterFence(func(QAWriterToken) error { return nil })

	firstPlan, _ := FreezeQAEvidencePlan(sp.Project, sp.Slug, QAEvidencePlan{AttemptID: qaMap.SemanticAttemptID, ShardID: shard.ID, ExpectationRefs: shard.ExpectationRefs, Kind: QACheckFact, ConfirmationCondition: "p", RefutationCondition: "q", InconclusiveCondition: "r", ApprovedPaths: []string{"internal/a.go"}, Executable: "true", Timeout: time.Minute, OutputLimit: 1024, CleanupRequired: true, GovernedInputFingerprint: qaMap.GovernedInputFingerprint, ImplementationFingerprint: qaMap.ImplementationFingerprint, MapFingerprint: testQAFingerprint}, qaMap.Budgets, time.Unix(1000, 0))
	secondPlan, _ := FreezeQAEvidencePlan(sp.Project, sp.Slug, QAEvidencePlan{AttemptID: qaMap.SemanticAttemptID, ShardID: shard.ID, ExpectationRefs: shard.ExpectationRefs, Kind: QACheckFact, ConfirmationCondition: "p", RefutationCondition: "q", InconclusiveCondition: "r", ApprovedPaths: []string{"internal/a.go"}, Executable: "true", Timeout: time.Minute, OutputLimit: 1024, CleanupRequired: true, GovernedInputFingerprint: qaMap.GovernedInputFingerprint, ImplementationFingerprint: qaMap.ImplementationFingerprint, MapFingerprint: testQAFingerprint}, qaMap.Budgets, time.Unix(2000, 0))
	if firstPlan.ID != secondPlan.ID {
		t.Fatalf("plan ID changed with FrozenAt: %s vs %s", firstPlan.ID, secondPlan.ID)
	}
	if firstPlan.FrozenAt.Equal(secondPlan.FrozenAt) {
		t.Fatal("expected FrozenAt to differ between runs")
	}

	bundle1, assessment1 := probeEvidenceBundle(t, sp, qaMap, shard, time.Unix(1000, 0))
	state1 := publication.State
	state1.Phase = QAPhaseCompleted
	state1.CurrentAttemptID = qaMap.SemanticAttemptID
	state1.NextAction = "done"
	pub1 := publication
	pub1.State = state1
	pub1.Evidence = &bundle1
	if err := store.Publish(pub1, token); err != nil {
		t.Fatalf("first evidence publish failed: %v", err)
	}

